interventions_raw:
[{"type": "BEHAVIORAL", "name": "In-person physiotherapist led integrated healthy lifestyle and pain care", "description": "Participants allocated to in-person intervention will be offered:

A) Up to four in-person physiotherapist consultations (up to one hour in duration) over 12 weeks (weeks 1, 3, 6, and 12);

B) Tailored pain education and healthy lifestyle education and resource bundles, including video content, web resources and interactive tools sent to participants via email or text;

C) Referral to telephone-based population wide health behaviour change support services, the NSW Get Healthy Coaching and information service and the Quitline for smokers, by the week 12 consultation (up to 6 telehealth consultations).

Total = up to 10 consultations over 6 months.", "armGroupLabels": ["In-person physiotherapist-led pain and lifestyle care"]}, {"type": "BEHAVIORAL", "name": "Virtual multidisciplinary integrated healthy lifestyle and pain care", "description": "Participants allocated to the virtual multidisciplinary intervention will receive:

A) 10 consultations over 6 months with a multidisciplinary team, including a minimum 4 with a physiotherapist (week 1, 3, 6, 12) and remainder with a dietitian and/or psychologist, tailored to participants needs. Virtual care consultations may be individual or joint multidisciplinary sessions conducted on standard virtual care platforms used by NSW Health. Consultation will be up to one hour in duration, or use an equivalent total duration with a higher frequency schedule. Where appropriate, participants may be referred to alcohol or smoking cessation support, including individualised virtual or telephone-based counselling with access to nicotine replacement therapy;

B) Tailored pain education and healthy lifestyle education and resource bundles, including video content, web resources and interactive tools sent to participants via email or text.", "armGroupLabels": ["Virtual multidisciplinary pain and lifestyle care"]}]

[{"type": "BEHAVIORAL", "name": "exercise program supervised by specialized kinesiologists", "description": "The duration of the program is 12 weeks, with 2 sessions per week of mixed activities (aerobic exercises + muscle strengthening exercises). Each session lasts about 60 minutes, including a warm-up phase, a central phase and a cool-down phase. In particular, for aerobic exercises, the central phase involves the use of various ergometers (e.g. treadmill and cycle ergometer) and a moderate intensity of training (55-69% of Heart Rate Reserve), while for muscle strengthening exercises will be administered bodyweight exercises, with small tools (e.g. elastic bands, medicine ball, etc.) or with isotonic machines (e.g. lat machines and leg presses), with an initial work intensity of 45-50% of One Repetition Maximum.", "armGroupLabels": ["Group 2, n° 70 people with migraine in standard treatment + adapted exercise program supervised"]}, {"type": "OTHER", "name": "Standard neurological visit at the Headache Centre", "description": "Participants will be invited to participate a:

1. \- specialist visit at the Headache Centre;
2. a - anthropometric, metabolic, and dietary assessment;

2b - self-administered (via a digital, online, form divided into four parts) and researcher-administered questionnaires; 2c - kinesiological assessment of functional capacities (aerobic capacity, muscle strength and flexibility); 2d - complete postural evaluation (divided into objective, instrumental, functional and neuromotor examination); 2e - traditional/complete gnathological evaluation, according to international diagnostic criteria.", "armGroupLabels": ["Group 1, 70 people with migraine in standard treatment (control arm).", "Group 2, n° 70 people with migraine in standard treatment + adapted exercise program supervised"]}]
